1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	</style>
32	</head>
33	<body>
34	<div class="calc">
35	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
36	  <div class="keys">
37	    <button class="clear wide" data-testid="key-clear">AC</button>
38	    <button class="clear" data-testid="key-sign">±</button>
39	    <button class="op" data-testid="key-div" data-op="/">÷</button>
40	    <button class="clear wide" data-testid="key-lparen">(</button>
41	    <button class="clear wide" data-testid="key-rparen">)</button>
42	    <button data-testid="key-7" data-digit="7">7</button>
43	    <button data-testid="key-8" data-digit="8">8</button>
44	    <button data-testid="key-9" data-digit="9">9</button>
45	    <button class="op" data-testid="key-mul" data-op="*">×</button>
46	    <button data-testid="key-4" data-digit="4">4</button>
47	    <button data-testid="key-5" data-digit="5">5</button>
48	    <button data-testid="key-6" data-digit="6">6</button>
49	    <button class="op" data-testid="key-sub" data-op="-">−</button>
50	    <button data-testid="key-1" data-digit="1">1</button>
51	    <button data-testid="key-2" data-digit="2">2</button>
52	    <button data-testid="key-3" data-digit="3">3</button>
53	    <button class="op" data-testid="key-add" data-op="+">+</button>
54	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
55	    <button data-testid="key-dot">.</button>
56	    <button class="op" data-testid="key-equals">=</button>
57	  </div>
58	</div>
59	<script>
60	  var entry = "0";      // text of the current entry or last result
61	  var stored = null;    // left operand
62	  var op = null;        // pending operator
63	  var fresh = true;     // next digit starts a new entry
64	  var waiting = false;  // an operator was just pressed and has no right operand yet
65	  var error = false;    // set by a non-finite result; only clear leaves it
66	  var groups = [];      // outer {stored, op} saved by each open parenthesis
67	
68	  var display = document.querySelector('[data-testid="calc-display"]');
69	
70	  function compute(a, b, o) {
71	    if (o === "+") return a + b;
72	    if (o === "-") return a - b;
73	    if (o === "*") return a * b;
74	    return a / b;
75	  }
76	
77	  // Presentation only: at most 10 significant digits, no trailing zeros,
78	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
79	  function format(v) {
80	    if (v === 0) return "0";
81	    var r = Number(v.toPrecision(10));
82	    var a = Math.abs(r);
83	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
84	    var e = Math.floor(Math.log10(a));
85	    if (Math.pow(10, e) > a) e--;
86	    var s = r.toFixed(Math.max(0, 9 - e));
87	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
88	  }
89	
90	  // While typing, the entry shows exactly as typed; results are formatted.
91	  function render() {
92	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
93	    display.setAttribute("data-value", String(Number(entry)));
94	    display.setAttribute("data-error", String(error));
95	  }
96	
97	  function digit(d) {
98	    if (fresh) { entry = d; fresh = false; }
99	    else entry = entry === "0" || entry === "-0" ? entry.slice(0, -1) + d : entry + d;
100	    waiting = false;
101	  }
102	
103	  function dot() {
104	    if (fresh) { entry = "0."; fresh = false; }
105	    else if (entry.indexOf(".") === -1) entry += ".";
106	    waiting = false;
107	  }
108	
109	  // Acts on the current entry. A typed entry keeps its text; a result is negated as a value.
110	  function sign() {
111	    if (!fresh) entry = entry.charAt(0) === "-" ? entry.slice(1) : "-" + entry;
112	    else entry = String(-Number(entry));
113	    waiting = false;
114	  }
115	
116	  // Immediate execution: each operator finishes the waiting operation, strictly
117	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
118	  function operator(o) {
119	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
120	    stored = Number(entry);
121	    op = o;
122	    fresh = true;
123	    waiting = true;
124	  }
125	
126	  // Division by zero (or any non-finite result) enters the error state.
127	  function finish(result) {
128	    entry = String(result);
129	    if (!isFinite(result)) error = true;
130	  }
131	
132	  // A group saves the outer operation and starts a fresh one inside.
133	  // Inside a group the same left-to-right rule applies.
134	  function lparen() {
135	    groups.push({ stored: stored, op: op });
136	    entry = "0"; stored = null; op = null; fresh = true; waiting = false;
137	  }
138	
139	  // Closing finishes the inner operation; its result becomes the outer right operand.
140	  function rparen() {
141	    if (groups.length === 0) return;
142	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
143	    var g = groups.pop();
144	    stored = g.stored;
145	    op = g.op;
146	    fresh = true;
147	    waiting = false;
148	  }
149	
150	  // Equals closes any open groups first.
151	  function equals() {
152	    while (groups.length && !error) rparen();
153	    if (op === null || error) return;
154	    finish(compute(stored, Number(entry), op));
155	    stored = null;
156	    op = null;
157	    fresh = true;
158	    waiting = false;
159	  }
160	
161	  function clear() {
162	    entry = "0"; stored = null; op = null; fresh = true; waiting = false; error = false; groups = [];
163	  }
164	
165	  document.querySelector(".keys").addEventListener("click", function (e) {
166	    var b = e.target.closest("button");
167	    if (!b) return;
168	    var id = b.getAttribute("data-testid");
169	    if (error && id !== "key-clear") return;
170	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
171	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
172	    else if (id === "key-dot") dot();
173	    else if (id === "key-sign") sign();
174	    else if (id === "key-lparen") lparen();
175	    else if (id === "key-rparen") rparen();
176	    else if (id === "key-equals") equals();
177	    else if (id === "key-clear") clear();
178	    render();
179	  });
180	
181	  render();
182	</script>
183	</body>
184	</html>
